import re

def parse_amount(val):
    if not isinstance(val, str): return float('nan')
    val = val.strip()
    if not val: return float('nan')

    is_negative = False
    if "CR" in val:
        is_negative = True
    elif val.startswith("(") and val.endswith(")"):
        is_negative = True
    elif "-" in val:
        is_negative = True

    val = val.replace("C1", "").replace("C2", "")
    val = re.sub(r'[^0-9,\.]', '', val)

    seps = [c for c in val if c in [',', '.']]
    decimal_sep = None
    if ',' in seps and '.' in seps:
        decimal_sep = seps[-1]
    elif len(set(seps)) == 1:
        sep = seps[0]
        last_idx = val.rfind(sep)
        if len(val) - 1 - last_idx == 2:
            decimal_sep = sep

    if decimal_sep:
        parts = val.rsplit(decimal_sep, 1)
        parts[0] = re.sub(r'[,.]', '', parts[0])
        parts[1] = re.sub(r'[,.]', '', parts[1]) # just in case
        val = parts[0] + '.' + parts[1]
    else:
        val = re.sub(r'[,.]', '', val)

    try:
        f = float(val)
        return -f if is_negative else f
    except:
        return float('nan')

print(parse_amount(" 1,234.56 CR "))
print(parse_amount(" 1,234,567 "))
print(parse_amount(" 1,234,56 "))
print(parse_amount("1,000.50"))
print(parse_amount("1.000,50"))
